"title": "注塑熔接痕：位置由浇口定、深浅由前锋温差定",
"summary": "熔接痕（又叫熔接线、夹水线、夹水纹）是两股料流前锋相遇时界面没有完全熔合留下的线。赫兹工业设计把它拆成两个独立问题：**位置**由浇口和型腔几何决定，浇口挪 10 mm，痕就换一条边，调机挪不动它；**深浅**由前锋温差、料温、模温、流速和排气决定，温差 < 20 ℃ 基本看不见，> 40 ℃ 是抛光和喷涂都盖不住的暗线。B 站专栏「模具知识 11」给出的 Moldflow 判据更严：前锋温差 > 10 ℃ 熔接线就很明显。它还列出结构侧的手段：在汇合处加骨位，把痕引过去。",
