"title": "Nord-Lock 楔形防松垫圈：楔角大于螺纹升角的成对拉伸锁紧",
"summary": "Nord-Lock 原厂楔形锁紧垫圈成对使用：相互贴合的一面是楔形凸轮，朝向螺头/螺母和被连接件的一面是径向细齿。因为楔角 α 大于螺纹升角 β，螺栓一旦有松转趋势，就会沿凸轮面把一对垫圈撑开、进一步拉伸螺栓、增大夹紧力——这是**靠拉伸（tension）锁紧**，不是靠弹簧垫圈的弹力，也不是靠尼龙圈摩擦。钢垫圈（EN 1.7182）规格大约 M3–M130，硬度 ≥ 465 HV1，推荐温度 −50 °C 到 200 °C；垫圈必须比接触面硬。",
