"slug": "尼龙嵌件锁紧螺母（DIN 985 Nyloc）：预紧力矩、120°C 上限与安装方向",
"title": "尼龙嵌件锁紧螺母（DIN 985 Nyloc）：预紧力矩、120°C 上限与安装方向",
"summary": "Nyloc（尼龙嵌件锁紧螺母）在六角螺母顶部压入一圈内径略小于螺栓外径的尼龙环：螺栓先穿过金属螺纹，再挤入尼龙，尼龙弹性变形产生与夹紧力无关的预紧力矩（prevailing torque），用来抵抗振动松动。标准尼龙大约在 −40 °C 至 +120 °C 保持抓力；超过约 120 °C 会软化，持续高于 130–140 °C 会永久变形。必须从金属螺纹端旋入，让尼龙环最后啮合。",
