"title": "开口弹簧垫圈防松失效（反面案例）：压平后在横向振动中几乎无效",
"summary": "开口螺旋弹簧垫圈被广泛当成“防松件”，但在横向振动（Junker，DIN 65151）里几乎没有防松作用，有时还会加快松脱。原因很直接：拧到目标预紧后垫圈已经被压平，弹力可以忽略，剩下的只是一片被压扁的开口垫圈。Bolt Science 用 M8 接头做了对比试验，并指出 8.8 级及以上螺栓上，这类垫圈往往在目标预紧的约 10%–20% 就已经压平；1969 年 Junker 的工作已经表明它不能阻止松转。本篇作为反面案例，对照楔形垫圈（拉伸锁紧）和 Spiralock（改变内螺纹牙型）：不要再把弹簧垫圈当防松件。",
