"title": "抽芯铆钉（盲铆钉）：钉套、钉芯与断颈槽，开口型与封闭型",
"summary": "抽芯铆钉由钉套（铆体）和钉芯（钉杆）组成，从单面插入预钻孔，拉枪拉动钉芯使钉套在背面膨胀形成墩头，钉芯在预设断颈槽处拉断。它和拉铆螺母都是单面施工，但拉铆螺母留下可重复使用的内螺纹，抽芯铆钉是一次性永久夹紧。选型关键是夹紧范围必须覆盖工件总厚，并分清开口型（钉芯主体多被抽走、钉套空腔不密封）与封闭型（钉套尾部封闭，利于防水）。",
