"summary": "拉铆螺母是单面安装的内螺纹紧固件：把它插入预制孔，拉枪螺杆拧入并回拉，薄壁在板背面塑性镦成鼓包，把板夹在法兰和鼓包之间，再旋出螺杆，板上留下内螺纹。和压铆螺母不同，它不靠双面加压让板料冷流进退刀槽，关键参数是**铆接范围（夹持厚度）必须覆盖实际叠层厚度**，以及圆孔滚花（摩擦防转）还是六角孔（机械防转）。",
