"summary": "压铆隔离柱（self-clinching standoff）把带通孔或盲孔螺纹的柱体压进冲好的圆孔，板料冷流进头部下方的槽，在两块板或 PCB 之间给出确定的间距；与压铆螺母不同，它的目的不是“几乎不增加板厚方向的支撑高度”，而是用规定的柱长 L 把两层撑开。PEM SO 通孔型例如 M3：孔径 4.22 mm（+0.08）、最小板厚 1 mm、孔心到边 6 mm、柱长系列 3–18 mm；板材必须比柱软（SO 型 HRB 80 / HB 150 以下）。",
