"slug": "十字交叉簧片枢轴（Cross-spring pivot）：交叉位置对寄生位移的影响与 C-Flex I-10 实例",
"title": "十字交叉簧片枢轴（Cross-spring pivot）：交叉位置对寄生位移的影响与 C-Flex I-10 实例",
"summary": "十字交叉簧片枢轴用两片（或三片）簧片交叉构成转动中心：簧片可以在中点相交（λ = 1/2），也可以把交点移开；中点交叉在 α = 45°、θ = 30° 时寄生位移约为 L/31，把交点移到 λ = 1/2 ± √5/6 可以消掉二阶的横向寄生，但会让其中一段簧变得很短、应力升高。商品上的 C-Flex I-10 把三片簧放在两个互不接触的不锈钢套筒里钎焊成一体，额定最大转角 ±15°，作为量产实例写在本篇，不再按品牌拆第二篇。",
