"summary": "笔记本屏幕、设备翻盖能「停在任意角度」，是因为铰链里的摩擦扭矩大于盖板重力产生的力矩。Reell 的 TI-C5M 扭力插件把一串淬火钢卡簧过盈套在淬火钢轴上，**每多一片卡簧就多一份扭矩**，所以用标准件就能拼出 0.15/0.25/0.30 N·m，寿命 3 万次；整个插件压入塑料或金属孔即可，不需要螺丝。Sugatsune 的选型文章给出计算方法：力矩 = 重量 × 重心到转轴距离，按铰链数平分，然后**要用铰链扭矩公差的下限去比**，例如标称 60 lbf·in ±10% 的铰链最低只有 54 lbf·in。",
