"summary": "舌片式安全门联锁把开关本体装在机器上、把专用执行器装在门上：关门时执行器插入并转动内凸轮，NC 触点靠弹簧力闭合，控制系统判定门已关闭；开门时凸轮把 NC 触点强制推开，切断电路，即使启动按钮被按下机器也不能再开。IDEC 强调这种「直接断开动作」要求执行器到 NC 触点之间只有非弹性结构，即使触点已经熔焊，开门的力仍能把触点分开。它不是普通限位开关，也不是用螺丝刀就能拨动的门磁。",
