"summary": "接触辅助十字簧片柔性铰（contact-aided CAFP）在普通十字交叉簧片旁边，加一块固定在机架上的接触块：朝某一侧转动时，其中一根簧片贴上接触面，自由长度被缩短，整铰刚度明显提高；朝另一侧转动时不接触，刚度仍接近原来的十字簧片。这样，同一个柔性转动副在顺时针和逆时针可以表现得不一样，而不必改成两套铰链。",
