"title": "旋转阻尼器（缓降盖板）：硅油黏性、水平型与垂直型的扭矩曲线",
"summary": "马桶盖「松手慢慢落下」靠的是一个装在转轴上的小油缸：转子在灌满硅油的壳体里转，油的黏性阻力产生制动扭矩。Bansbach 的结构说明讲清了它的三个特性：**温度越低扭矩越大、转速越快扭矩越大、原则上双向都有扭矩（要单向就加单向离合器）**，目录额定扭矩在 20 rpm 下测得。TOK 的目录给出选型方法：T = m × g × ℓ（例：0.408 kg、重心 0.25 m → 1.0 N·m），并且把限位角阻尼器分成「水平型」（越接近水平扭矩越大，用于马桶盖、垃圾桶盖）和「垂直型」（水平时最大，下垂时变小，用于面包柜、抽油烟机翻板）。",
