"summary": "典型汽车引擎盖锁把主锁和二次安全钩做在同一套锁体上：关上时，引擎盖上的锁扣环先推开保险钩，再推动棘轮转到与棘爪啮合，主锁锁死；从车内拉释放拉线只让棘爪脱离棘轮，引擎盖弹到半开并停在保险钩上，必须到车头手动拨开保险钩，锁扣环才能离开，盖子才能全开。美国 FMVSS No. 113 要求：前缘开启且在打开位置会挡住驾驶前方视线的引擎盖，必须有第二锁定位置或第二套锁。主锁承担行驶风压和振动，二次钩是防止主锁失效或误拉时盖子被掀起的安全件，不能在维修里被跳过或拆除。",
