"summary": "鼠标滚轮要把旋转方向和步进传给主控，常见有两条路：机械式编码器由滚轮带动转盘，转盘上的触点与底座固定触点时通时断，形成两路错开的开关信号；光栅式则在滚轮上开一圈格子，两侧用红外发射和接收，格子转过时光线被反复挡住或透过，芯片根据光脉冲的先后判断方向和速度。TTC 写道，机械式因为有触点摩擦，手感和定位比较明确，寿命从早期的 10 万圈发展到其 2017 年宣称的 200 万圈；光栅式工作时几乎没有实质性接触，稳定性好，但灯源会衰减。它不是旋钮电位器，也不是已经在库中的 EC11 那种带柄编码器本体的重复堆叠。",
