"title": "O 形圈密封槽设计：填充率、压缩率与挤出间隙的五个数",
"summary": "O 圈漏不漏，主要不看胶料，而看沟槽的几个数：填充率（静 ≤ 80%、动 ≤ 70%）、压缩率（一般 12%–30%，要用 O 圈最小/最大截面各算一遍）、挤出间隙（按最大实际间隙算，压力越高间隙要越小）、线速度、介质 + 温度。三家来源给的区间基本一致：Parker 手册建议填充 60%–85%、最佳 75%，静密封最大压缩 30%，绝对压缩量不少于 0.007 in（约 0.2 mm）。",
