"title": "FDM 一体打印活动件（Print-in-Place）：XY 每边 0.3 mm、Z 两整层的间隙规则",
"summary": "一体打印（Print-in-Place，PiP）是把铰链销和铰链孔、关节和关节窝按装配好的状态一次打出来，零件之间只靠一圈空气隔开。QIDI 给出的工作值是：0.4 mm 喷嘴、0.2 mm 层高下，**一体打印铰链每边 0.30–0.40 mm，球窝每边 0.35–0.50 mm，Z 向间隙取层高的整数倍且至少两层（0.4 mm）**；这大约是打印后再装配的销孔间隙（每边 0.15–0.25 mm）的两倍，因为熔在一起的一体件没法再磨开。B 站爱能特专栏（转述 Irv Shapiro 的教程）补充了做法：用「间隙 + 桥接」造出四周悬空的中间件，先打 0.2–0.6 mm 五孔测试块确认机器精度。",
