"summary": "MuCell 微发泡把超临界氮气或二氧化碳溶进熔体，注射进型腔后靠泡孔成核、生长来填满并「保压」，不再依赖注塑机的高压保压。结构上的直接后果是：加强筋不必再按实心件 0.4–0.6 倍壁厚去削薄。伊之密写明可以「实现 1:1 的主壁与筋位结构」；Trexel 手册把同一条写成 Rib to wall thickness ratios of 1:1，并配对照图：常规设计筋明显细于主壁，MuCell 设计允许筋厚等于公称壁厚且不出现缩痕。它和 发泡件缩水：模温、排气与保压和实心件相反、气体辅助注塑（GAIM）：用气道掏空厚筋消缩痕 都在处理厚区收缩，但本篇的主角是筋壁比这条设计规则为什么可以放宽。",
