"title": "换料收缩率：同一张图换料就裂，图纸必须按新缩水放缩",
"summary": "模具型腔是按某一种料的收缩率反向放大做出来的；同一张成品 3D 图换料却不重新放缩，得到的是系统性尺寸偏差，止口、卡扣和柱距会一起错。要在模型里按新料缩水率重新放缩，并核对流向各向异性和后收缩，而不是只改 BOM 或图纸角上的一个系数。",
