"summary": "折叠屏转轴有轴盖、支架、摆臂、阻尼、同步、门板等几十个零件。荣耀专利 CN121952969A（申请日 2024-10-29）把其中会相对运动的零件，例如基座和摆臂，用金属 3D 打印**一次打成一个组合件**，彼此之间用薄壁或细杆状的「连接余料」临时连住；打完用激光切掉余料，原来余料占的位置就变成转动间隙。关键规则是**所有与余料相连的面都垂直于打印方向**，让余料像一面立着的薄墙，切割时不被零件挡住；台阶处统一用 135° 斜面自支撑。",
