"slug": "金属注射成型（MIM）：均匀壁厚、烧结支撑面与 5000 件成本拐点",
"title": "金属注射成型（MIM）：均匀壁厚、烧结支撑面与 5000 件成本拐点",
"summary": "MIM 是把金属粉和粘结剂混成喂料，像塑料一样注塑出「生坯」，再脱掉粘结剂、高温烧结成致密金属件，线收缩 12%–20%（316L 约 15%–18%）。赫兹工业设计给出两条硬规则：**翘曲多半在开模前就注定了**，要做到壁厚 1–4 mm 且同件壁厚差 ±10% 以内、进胶对称、留出烧结支撑面；**成本拐点 =（MIM 模具投入 − CNC 编程夹具投入）÷（CNC 单件 − MIM 单件）**，再乘 1.5–2 作为起订量，小件大多落在 5000–3 万件。德国 MIMplus 的设计指南从工厂角度给出同样的原则：最小壁厚 0.3–0.5 mm、尽量避免截面 > 5 mm、拔模 1°、需要尽量平的烧结接触面，以及按尺寸分档的公差表。",
