"slug": "铝件阳极氧化的尺寸链：膜厚一半向外、遮蔽螺纹与挂点",
"title": "铝件阳极氧化的尺寸链：膜厚一半向外、遮蔽螺纹与挂点",
"summary": "阳极氧化膜是从铝基体「长出来」的转化膜，不是镀上去的。两家来源都用**「约一半向内、一半向外」**做初步估算：25 μm 硬质膜外表面偏移 12.5 μm，内孔缩小一整个膜厚（Five Flute）。仲德精密补上两件经常被忘的事：**前处理（碱蚀、化学梨地）会先溶掉基材**；加上膜厚公差后，阳极前的加工窗口反而比成品公差更窄（Ø50 H8 + 30 ± 5 μm 硬质膜，阳极前孔径须控制在 Ø50.035–50.064 mm）。严公差只有三条路：预补偿、遮蔽、氧化后精加工。挂点（导电接触点）没有膜，必须由设计师在图纸上指定。",
